docker exec startuphafen-devcontainer-maildev-1 node -e "
const net=require('net');
const s=net.connect(1025,'127.0.0.1');
let st=0;
const lines=['EHLO validator','MAIL FROM:<test@startuphafen.de>','RCPT TO:<user@example.com>','DATA','From: noreply@startuphafen.de','To: user@example.com','Subject: validation-test','Content-Type: text/plain','','This is a maildev validation email.','','.','QUIT'];
s.on('data',()=>{
  if(st<lines.length){ s.write(lines[st]+'\r\n'); st++; }
  else s.end();
});
s.on('end',()=>{ console.log('SMTP session done'); process.exit(0); });
setTimeout(()=>{ console.log('TIMEOUT at step',st); process.exit(1);},6000);
"
sleep 1
